#include <iostream>
#include <algorithm>
#include <string>
#include <cmath>
#define MAX_LEVEL_COUNT 18
typedef long long ll;
using namespace std;

ll precomputed[MAX_LEVEL_COUNT];

int calculate(ll number, int level) {
    int count = number / precomputed[level];
    number %= precomputed[level];

    if (number == 0)
        return level * count;
    return level * count + min(level + calculate(precomputed[level] - number, level - 1), calculate(number, level - 1));
}

int main() {
    precomputed[0] = 0;
    for (int i = 1; i < MAX_LEVEL_COUNT; i++)
        precomputed[i] = precomputed[i - 1] * 10 + 1;

    ll input_value;
    while (cin >> input_value) {
        cout << calculate(input_value, MAX_LEVEL_COUNT - 1) << endl;
    }
}
